/**
 * Whether Today's one-line messages want to show, apart from the banners
 * that draw them: the card that suggests another surface (NudgeSlot) shares
 * their place and stays away while one of them is up.
 */
import { getMeta } from '@/db/schema.js';
import { countWords, listNotebooks, loadSettings } from '@/db/repo.js';
import { isNativeShell } from '@/lib/platform/detect.js';
import { platform } from '@/lib/platform/index.js';
import { safeExternalUrl } from '@/lib/externalLinks.js';
import { isNewer } from '@/lib/updates.js';
import { progress } from '@/features/getstarted/steps.js';

/**
 * Whether to offer the reminder. Only the shells can deliver one; only to
 * somebody who has no reminder, has not said no, and has words to be
 * reminded of. While the getting-started list is open it asks the same
 * question as one of its steps, so this stays quiet until the list is done.
 */
export async function shouldOffer(): Promise<boolean> {
  if (!isNativeShell()) return false;
  const [settings, dismissed, list] = await Promise.all([
    loadSettings(),
    getMeta('reminderOfferDismissed'),
    getMeta('getStarted'),
  ]);
  if (dismissed || (settings?.reminderTime ?? '') !== '') return false;
  if (list?.offered === true && !(await progress()).complete) return false;
  for (const notebook of await listNotebooks()) {
    if ((await countWords(notebook.id)) > 0) return true;
  }
  return false;
}

export interface Offer {
  version: string;
  url: string;
}

/** The newer Android build the update line offers, or null: sideloaded builds only. */
export async function loadOffer(): Promise<Offer | null> {
  const [known, dismissed] = await Promise.all([getMeta('updateCheck'), getMeta('updateDismissed')]);
  if (known === null || !isNewer(known.version, platform.env.appVersion)) return null;
  if (dismissed === known.version) return null;
  // Checked again here: an answer stored by an older build was never checked.
  const url = safeExternalUrl(known.url, 'update');
  if (url === undefined) return null;
  return { version: known.version, url: url.href };
}
