import { useEffect, useMemo, useRef, useState } from 'react';
import type { ApiNudgeEvent, ApiNudgeId } from '@/api/types.js';
import { Toast } from '@/components/ui/Toast.js';
import { getMeta } from '@/db/schema.js';
import { t } from '@/i18n/index.js';
import { localTimeZone } from '@/lib/format.js';
import { currentDevice, extensionStore, type Device } from '@/lib/platform/device.js';
import { platform } from '@/lib/platform/index.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { useAuth } from '@/features/auth/session.js';
import { NudgeCard, type NudgeAction } from '@/features/everywhere/NudgeCard.js';
import {
  DESKTOP_PAGE_URL,
  EXTENSION_PAGE_URL,
  EXTENSION_STORES,
  NUDGE_REF,
  PLAY_URL,
  withRef,
} from '@/features/everywhere/links.js';
import { pickNudge } from '@/features/everywhere/rules.js';
import {
  arrival,
  keepAppSessionAlive,
  loadSignals,
  recordNudge,
  refreshNudges,
  refreshSurfaces,
  touchAppSession,
} from '@/features/everywhere/state.js';
import { ConnectAssistantSheet } from '@/features/settings/ConnectAssistantSheet.js';
import { loadOffer, shouldOffer } from './offers.js';

/**
 * Everything the choice needs, read from IndexedDB: the server's copy of the
 * rules and history, what the account used, and this device's own signals.
 * Nothing here writes; the writes happen in the effects below.
 */
async function loadSlot() {
  const [nudges, surfaces, snoozed] = await Promise.all([
    getMeta('nudges'),
    getMeta('surfaces'),
    getMeta('verifySnoozedUntil'),
  ]);
  if (nudges === null || surfaces === null) return null;
  const [reminder, update, signals] = await Promise.all([
    shouldOffer(),
    loadOffer(),
    loadSignals(localTimeZone()),
  ]);
  return {
    view: nudges.view,
    surfaces: surfaces.list,
    signals,
    // The other messages that live in the same place on Today.
    otherMessage: reminder || update !== null,
    verifySnoozed: snoozed !== null && snoozed > Date.now(),
  };
}

/** The main button of each card, on this device. */
function actionFor(
  id: ApiNudgeId,
  device: Device,
  open: { send: (url: string) => void; connect: () => void },
): NudgeAction | undefined {
  const ref = NUDGE_REF[id];
  switch (id) {
    case 'extension': {
      const store = extensionStore(device);
      if (store === undefined) return undefined;
      return {
        kind: 'link',
        href: withRef(EXTENSION_STORES[store], ref),
        label: store === 'firefox' ? 'everywhere.addFirefox' : 'everywhere.addChrome',
      };
    }
    case 'desktop_safari':
      return { kind: 'link', href: withRef(DESKTOP_PAGE_URL, ref), label: 'nudge.desktop_safari.action' };
    case 'on_your_computer':
      return {
        kind: 'button',
        label: 'nudge.on_your_computer.action',
        run: () => {
          open.send(withRef(EXTENSION_PAGE_URL, ref));
        },
      };
    case 'on_your_phone':
      return { kind: 'link', href: withRef(PLAY_URL, ref), label: 'nudge.on_your_phone.action' };
    case 'android_browser':
      return { kind: 'link', href: withRef(PLAY_URL, ref), label: 'nudge.android_browser.action' };
    case 'connector':
      return { kind: 'button', label: 'nudge.connector.action', run: open.connect };
    case 'desktop_power':
    case 'kindle':
      return undefined;
  }
}

/**
 * The one place on Today where a card may suggest another surface (the
 * extension, ChatGPT or Claude, and later the apps). It sits below the
 * day's plan and shows at most one card an app session, and none while the
 * reminder offer, an update or the confirm-your-address line is showing:
 * those share this slot. Which card, and whether, is `pickNudge`; what was
 * shown, tapped or put away goes to the server so the caps hold on every
 * device.
 */
export function NudgeSlot(): React.JSX.Element | null {
  const device = useMemo(() => currentDevice(), []);
  const user = useAuth((state) => state.user);
  const data = useLiveQuery(loadSlot, null, []);
  const [session, setSession] = useState<string | undefined>();
  const [closed, setClosed] = useState<string | undefined>();
  const [connecting, setConnecting] = useState(false);
  const [toast, setToast] = useState<string | undefined>();
  const shownFor = useRef<string | undefined>(undefined);

  // Read the server's answers again whenever Today opens or the app comes
  // back, and settle which app session this is.
  useEffect(() => {
    let live = true;
    const start = async (): Promise<void> => {
      void refreshSurfaces().catch(() => undefined);
      await refreshNudges().catch(() => undefined);
      const cached = await getMeta('nudges');
      if (cached === null) return;
      const id = await touchAppSession(cached.view.rules.sessionGapMinutes);
      if (live) setSession(id);
    };
    void start();
    const onVisible = (): void => {
      if (document.visibilityState === 'visible') void start();
      else void keepAppSessionAlive();
    };
    document.addEventListener('visibilitychange', onVisible);
    const offResume = platform.lifecycle.onResume(() => {
      void start();
    });
    return () => {
      live = false;
      document.removeEventListener('visibilitychange', onVisible);
      offResume();
    };
  }, []);

  const verifyShowing = user !== null && !user.emailVerified && data?.verifySnoozed !== true;
  const pick =
    data === null || session === undefined
      ? null
      : pickNudge({
          view: data.view,
          surfaces: data.surfaces,
          device,
          signals: data.signals,
          arrival: arrival(),
          session,
          slotTaken: data.otherMessage || verifyShowing,
          now: new Date(),
        });

  // A card on screen is a showing, once per app session.
  useEffect(() => {
    if (pick === null || session === undefined || data === null) return;
    const key = `${session}:${pick}`;
    if (shownFor.current === key) return;
    shownFor.current = key;
    if (data.view.recentShows.some((show) => show.session === session && show.id === pick)) return;
    void recordNudge(pick, 'shown', session).catch(() => undefined);
  }, [pick, session, data]);

  const record = (id: ApiNudgeId, event: ApiNudgeEvent): void => {
    if (session === undefined) return;
    setClosed(`${session}:${id}`);
    void recordNudge(id, event, session).catch(() => undefined);
  };

  const action =
    pick === null
      ? undefined
      : actionFor(pick, device, {
          send: (url) => {
            platform.share
              .link(url, t('everywhere.title'))
              .then((how) => {
                if (how === 'copied') setToast(t('everywhere.linkCopied'));
              })
              .catch(() => undefined);
          },
          connect: () => {
            setConnecting(true);
          },
        });

  const visible = pick !== null && action !== undefined && closed !== `${session ?? ''}:${pick}`;

  return (
    <>
      {visible && (
        <NudgeCard
          id={pick}
          action={action}
          onAct={() => {
            record(pick, 'tapped');
          }}
          onNotNow={() => {
            record(pick, 'not_now');
          }}
          onNever={() => {
            record(pick, 'never');
          }}
        />
      )}
      {connecting && (
        <ConnectAssistantSheet
          say={(message) => {
            setToast(message);
          }}
          initial={arrival() === 'claude' ? 'claude' : 'chatgpt'}
          onClose={() => {
            setConnecting(false);
          }}
        />
      )}
      {toast !== undefined && (
        <Toast
          message={toast}
          onDone={() => {
            setToast(undefined);
          }}
        />
      )}
    </>
  );
}
