import { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Icon, type IconName } from '@/components/ui/Icon.js';
import { Sheet } from '@/components/ui/Sheet.js';
import { me as meApi } from '@/api/endpoints.js';
import { Celebrate } from '@/features/billing/Celebrate.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { settingsPath } from '@/features/settings/paths.js';
import { EXTENSION_PAGE_URL, EXTENSION_STORES, withRef } from '@/features/everywhere/links.js';
import { currentDevice } from '@/lib/platform/device.js';
import { platform } from '@/lib/platform/index.js';
import {
  STEP_IDS,
  celebrated,
  noteCelebrated,
  noteExtension,
  progress,
  stopOffering,
  type StepId,
} from './steps.js';
import styles from './GetStarted.module.css';

/**
 * Where each step takes somebody who taps it, and the icon that names it.
 *
 * The extension has no route: `/connect-extension` is opened by the
 * extension itself, with a nonce, and a content script listening on it.
 * Sending somebody there before they have installed anything is backwards,
 * so that step opens the install panel below instead.
 */
const STEPS: Record<StepId, { icon: IconName; to: string | null }> = {
  word: { icon: 'plus', to: '/notebook?add=1' },
  ai: { icon: 'sparkles', to: '/ai' },
  practise: { icon: 'progress', to: '/session' },
  extension: { icon: 'grid', to: null },
  assistant: { icon: 'sparkles', to: settingsPath('connected-apps') },
  reminder: { icon: 'today', to: settingsPath('notifications') },
};

/** Which store to lead with. Everything not Firefox takes the Chrome one. */
function onFirefox(): boolean {
  return navigator.userAgent.includes('Firefox');
}

/**
 * The six things worth doing once, and what each one is for.
 *
 * This is a teaching aid, not a game. It says why a step matters rather than
 * what to tap, because somebody who understands why the extension exists
 * will use it next week and somebody who was told to press a button will
 * not. It disappears for good once finished, and can be put away before
 * that by anyone who does not want it.
 *
 * Opening it reads the account's sessions, which is the only way to know the
 * extension has been connected: the extension marks the words it adds like
 * any other, so nothing local gives it away. That read happens here rather
 * than on Today, which keeps Today rendering from IndexedDB on the first
 * frame as everything else does.
 */
export function GetStarted({ onClose }: { onClose: () => void }): React.JSX.Element {
  const navigate = useNavigate();
  const here = useLiveQuery(() => progress(), undefined, []);
  const [finishing, setFinishing] = useState(false);
  const [installing, setInstalling] = useState(false);
  const [sent, setSent] = useState(false);
  // A phone cannot run a browser extension, so the step offers to send the
  // link to a computer rather than store pages that lead nowhere here.
  const mobile = useMemo(() => currentDevice().mobile, []);

  // The extension leaves a session behind and nothing else. Asking once, on
  // open, is what lets that step ever tick.
  useEffect(() => {
    let live = true;
    void meApi
      .sessions()
      .then((sessions) => {
        if (live) void noteExtension(sessions.some((s) => s.platform === 'extension'));
      })
      .catch(() => undefined);
    return () => {
      live = false;
    };
  }, []);

  // The celebration belongs to the moment it is finished, and happens once.
  // Marking it done before showing it is deliberate: a tab closed mid-tick
  // should not queue the confetti up for the next visit.
  useEffect(() => {
    if (here?.complete !== true) return;
    void (async () => {
      if (await celebrated()) return;
      await noteCelebrated();
      setFinishing(true);
    })();
  }, [here?.complete]);

  if (finishing) {
    return (
      <Sheet title={t('start.title')} onClose={onClose}>
        <Celebrate onDone={onClose} />
      </Sheet>
    );
  }

  if (installing && mobile) {
    return (
      <Sheet title={t('start.extension.title')} onClose={onClose}>
        <div className={styles.body}>
          <p className={styles.lead}>{t('start.install.phoneLead')}</p>
          <button
            type="button"
            className={styles.storeButton}
            onClick={() => {
              void platform.share
                .link(withRef(EXTENSION_PAGE_URL, 'getstarted'), t('start.extension.title'))
                .then((how) => {
                  setSent(how === 'copied');
                })
                .catch(() => undefined);
            }}
          >
            <span>{t('start.install.send')}</span>
            <Icon name="arrowRight" size={17} weight={2.2} />
          </button>
          {sent && (
            <p className={styles.note} role="status">
              {t('everywhere.linkCopied')}
            </p>
          )}
          <p className={styles.note}>{t('start.install.then')}</p>
          <button
            type="button"
            className={styles.hide}
            onClick={() => {
              setInstalling(false);
            }}
          >
            {t('start.install.back')}
          </button>
        </div>
      </Sheet>
    );
  }

  if (installing) {
    // Both stores are offered whichever browser this is: somebody may read
    // in one browser and work in another.
    const first = onFirefox() ? 'firefox' : 'chrome';
    const second = first === 'firefox' ? 'chrome' : 'firefox';
    return (
      <Sheet title={t('start.extension.title')} onClose={onClose}>
        <div className={styles.body}>
          <p className={styles.lead}>{t('start.install.lead')}</p>
          <a
            className={styles.store}
            href={withRef(EXTENSION_STORES[first], 'getstarted')}
            target="_blank"
            rel="noopener noreferrer"
          >
            <span>{t(`start.install.${first}`)}</span>
            <Icon name="arrowRight" size={17} weight={2.2} />
          </a>
          <a
            className={styles.storeQuiet}
            href={withRef(EXTENSION_STORES[second], 'getstarted')}
            target="_blank"
            rel="noopener noreferrer"
          >
            <span>{t(`start.install.${second}`)}</span>
            <Icon name="arrowRight" size={17} weight={2.2} />
          </a>
          {/* The part people get stuck on: the connect page is opened by the
              extension, not by them. */}
          <p className={styles.note}>{t('start.install.then')}</p>
          <button
            type="button"
            className={styles.hide}
            onClick={() => {
              setInstalling(false);
            }}
          >
            {t('start.install.back')}
          </button>
        </div>
      </Sheet>
    );
  }

  const done = new Set<StepId>(here?.done ?? []);

  return (
    <Sheet title={t('start.title')} onClose={onClose}>
      <div className={styles.body}>
        <p className={styles.lead}>{t('start.lead')}</p>

        <ol className={styles.steps}>
          {STEP_IDS.map((id) => {
            const complete = done.has(id);
            return (
              <li key={id}>
                <button
                  type="button"
                  className={cx(styles.step, complete && styles.stepDone)}
                  disabled={complete}
                  onClick={() => {
                    const to = STEPS[id].to;
                    if (to === null) {
                      setInstalling(true);
                      return;
                    }
                    onClose();
                    void navigate(to);
                  }}
                >
                  <span className={cx(styles.mark, complete && styles.markDone)} aria-hidden="true">
                    {complete ? (
                      <Icon name="check" size={14} weight={2.6} />
                    ) : (
                      <Icon name={STEPS[id].icon} size={15} weight={2} />
                    )}
                  </span>
                  <span className={styles.text}>
                    <span className={styles.stepTitle}>{t(`start.${id}.title`)}</span>
                    <span className={styles.stepWhy}>{t(`start.${id}.why`)}</span>
                  </span>
                  {!complete && <Icon name="chevronRight" size={15} weight={2} className={styles.go} />}
                </button>
              </li>
            );
          })}
        </ol>

        <button
          type="button"
          className={styles.hide}
          onClick={() => {
            void stopOffering().then(onClose);
          }}
        >
          {t('start.hide')}
        </button>
      </div>
    </Sheet>
  );
}
